export type TaskStatus = 'todo' | 'in_progress' | 'review' | 'done' | 'blocked'
export type TaskPriority = 'low' | 'medium' | 'high' | 'critical'

export type Task = {
  id: string
  objectiveId: string
  title: string
  description?: string
  status: TaskStatus
  priority: TaskPriority
  assigneeId?: string
  assigneeName?: string
  dueDate?: string
  proofLinks: string[]
  proofUploads: string[]
  createdAt: string
  updatedAt: string
}
